package com.company.aiinterview.auth.controller; import com.company.aiinterview.auth.dto.request.*; import com.company.aiinterview.auth.dto.response.*; import com.company.aiinterview.auth.service.AuthService; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/auth") @RequiredArgsConstructor public class AuthController { private final AuthService authService; @PostMapping("/register") public UserResponseDto register(@RequestBody RegisterRequestDto request){ return authService.register(request);} @PostMapping("/login") public LoginResponseDto login(@RequestBody LoginRequestDto request){ return authService.login(request);} @GetMapping("/me") public UserResponseDto me(){ return authService.getCurrentUser(); } }
